-- #1691 - staff cancellation choices: who asked for the cancellation, and what the customer is told
-- about their money (refunded / not yet / a staff-written message). They pick the customer-facing
-- "what happens next" wording in the cancellation email and on the order page.
--
-- HAND-AUTHORED, not generated by `prisma migrate dev --create-only`: that command refuses on the
-- dev database ("The migration `20260820200500_p8_image_needs_review` was modified after it was
-- applied") and offers only `migrate reset`, which would delete every row - the open `#895`. The DDL
-- below is Prisma's own output, unedited, from `prisma migrate diff --from-schema-datamodel
-- <staging schema> --to-schema-datamodel prisma/schema.prisma --script`, so it touches no database
-- and cannot propose removing the hand-authored `pg_trgm` indexes (`#508`).
--
-- Purely additive: two enums and three nullable columns, no default, no backfill. Every existing row
-- stays NULL, which keeps the original cancellation wording for it.

-- CreateEnum
CREATE TYPE "CancellationReason" AS ENUM ('CUSTOMER_REQUEST', 'STORE_UNABLE', 'OTHER');

-- CreateEnum
CREATE TYPE "CancellationMessage" AS ENUM ('REFUNDED', 'NOT_REFUNDED', 'CUSTOM');

-- AlterTable
ALTER TABLE "OrderStatusEvent" ADD COLUMN     "cancellationMessage" "CancellationMessage",
ADD COLUMN     "cancellationReason" "CancellationReason",
ADD COLUMN     "customerMessage" TEXT;
